// lib/game_ui_localization.dart
// Internationalisation complète des écrans de jeu, des salons, des équipes et du matchmaking.
// Support exhaustif des 22 langues configurées dans l'application :
// fr, en, es, de, it, pt, nl, pl, ru, uk, ro, el, cs, sv, da, fi, no, hu, sk, hr, bg, tr.

import 'dart:ui' as ui;
import 'package:flutter/widgets.dart';

class GameUiLocalization {
  /// Traduit une clé ou un texte français brut selon la langue du context Flutter.
  static String tr(BuildContext? context, String keyOrText, [Map<String, String>? params]) {
    String lang = 'fr';
    if (context != null) {
      try {
        final loc = Localizations.maybeLocaleOf(context);
        if (loc != null) lang = loc.languageCode.toLowerCase();
      } catch (_) {
        lang = 'fr';
      }
    } else {
      try {
        lang = ui.PlatformDispatcher.instance.locale.languageCode.toLowerCase();
      } catch (_) {
        lang = 'fr';
      }
    }
    return trLang(lang, keyOrText, params);
  }

  /// Version sans BuildContext, basée sur le code langue (ex: 'fr', 'en', 'es', ...)
  static String trLang(String lang, String keyOrText, [Map<String, String>? params]) {
    final code = lang.toLowerCase();
    String? translation;

    // 1. Chercher par clé exacte
    if (_strings.containsKey(keyOrText)) {
      final map = _strings[keyOrText]!;
      translation = map[code] ?? map['en'] ?? map['fr'] ?? keyOrText;
    } 
    // 2. Chercher par texte français de référence
    else if (_frenchToKey.containsKey(keyOrText)) {
      final key = _frenchToKey[keyOrText]!;
      final map = _strings[key]!;
      translation = map[code] ?? map['en'] ?? map['fr'] ?? keyOrText;
    } 
    // 3. Fallback direct sur le texte
    else {
      translation = keyOrText;
    }

    if (params != null && params.isNotEmpty) {
      params.forEach((placeholder, value) {
        translation = translation!
            .replaceAll('{' + placeholder + '}', value)
            .replaceAll('{' + placeholder.toLowerCase() + '}', value)
            .replaceAll('{' + placeholder.toUpperCase() + '}', value);
      });
    }

    return translation ?? keyOrText;
  }

