extension GameLocalizationExt on String {
  /// Raccourci syntaxique pour traduire directement une chaîne dans le contexte Flutter :
  /// `"Salon Privé".trGame(context)`
  String trGame(BuildContext context, [Map<String, String>? params]) {
    return GameUiLocalization.tr(context, this, params);
  }
}
